package com.franco.desco.application.cultivation.service;
import com.franco.desco.application.cultivation.CultivationCommands.*;import com.franco.desco.application.cultivation.port.in.CultivationUseCase;import com.franco.desco.application.cultivation.port.out.CultivationPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.cultivation.CultivationModels;
public final class CultivationApplicationService implements CultivationUseCase{private final CultivationPersistencePort p;public CultivationApplicationService(CultivationPersistencePort p){this.p=p;}public AppResult<PageResult<CultivationModels.Summary>>list(ListCultivations c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"CULTIVOS_LISTADOS","CULTIVOS_NO_LISTADOS",AppStatus.BAD_REQUEST);}public AppResult<CultivationModels.Detail>get(GetCultivation c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.get(c,i,m),"CULTIVO_OBTENIDO","CULTIVO_NO_DISPONIBLE",AppStatus.NOT_FOUND);}public AppResult<Long>createPlot(CreatePlot c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.createPlot(c,i,m),"PARCELA_CREADA","PARCELA_NO_CREADA");}public AppResult<Void>updatePlot(UpdatePlot c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.updatePlot(c,i,m),"PARCELA_ACTUALIZADA","PARCELA_NO_ACTUALIZADA",AppStatus.BAD_REQUEST);}public AppResult<Long>createCrop(CreateCrop c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.createCrop(c,i,m),"CULTIVO_CREADO","CULTIVO_NO_CREADO");}public AppResult<Void>updateCrop(UpdateCrop c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.updateCrop(c,i,m),"CULTIVO_ACTUALIZADO","CULTIVO_NO_ACTUALIZADO",AppStatus.BAD_REQUEST);}public AppResult<Void>finishCrop(FinishCrop c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.finishCrop(c,i,m),"CULTIVO_FINALIZADO","CULTIVO_NO_FINALIZADO",AppStatus.BAD_REQUEST);}}
